{
    StateRequirements myactionRequirements = new StateRequirements();
    myactionRequirements.reqId = actReq.Id;
    myactionRequirements.id = state.Id;
    myactionRequirements.name = state.name;
    myactionRequirements.minimalPoinst = actReq.MinValue;
    myactionRequirements.currentStatePoints = state.points;
    myactionRequirements.pointsName = state.pointsName;
    if (state.points < myactionRequirements.minimalPoinst)
    {
        actionExt.status = "Error";
        actionExt.enabled = false;
        myactionRequirements.status = "Not enough " + state.pointsName + " to minimal requirements";

        actionExt.problems +=""+ myactionRequirements.status+"";
        actionExt.errors.Add(state.name + ":" + myactionRequirements.status);
    }
    myactionRequirements.costPoinst = actReq.Cost;
    if (state.points < myactionRequirements.costPoinst)
    {
        actionExt.status = "Error";
        myactionRequirements.status = "Not enough " + state.pointsName + " on balance";
        actionExt.problems += "" + myactionRequirements.status + "";
        actionExt.errors.Add(state.name + ":" + myactionRequirements.status);
        actionExt.enabled = false;
    }
    myactionRequirements.additionalPoinst = actReq.Addition;
    myactionRequirements.regularity = actReq.Regularity;
    actionExt.statesRequirements.Add(myactionRequirements);
    return myactionRequirements;
}

